<?php
declare(strict_types=1);
function simpleTrialCases(array &$tests,ControlCenter\Application $app,ControlCenter\Config $config,array $owner,array $other,HttpFixture $http,string $password):void {
    $setup=null;$offers=null;$policies=null;$seller=null;$tenant=null;$brand=null;$artifacts=null;$catalogCalls=0;$provisions=0;$plans=[];$c=null;$catalogDown=false;
    $register=function(string $version,int $code,int $revision)use($app,$owner,&$brand,&$artifacts):void {$id=ControlCenter\Database::id();$app->db->query('INSERT INTO app_brand_builds (id,brand_id,brand_version,app_version,manifest,requested_by,build_channel) VALUES (?,?,?,?,?,?,?)',[$id,$brand['id'],$revision,$version,json_encode(['app_version'=>$version,'app_version_code'=>$code]),$owner['id'],'testing']);$artifacts->recordVerified($id,['channel'=>'testing','package_name'=>$brand['package_name'].'.test','version_name'=>$version.'.'.$revision.'-test','version_code'=>$code*100000+$revision,'trial_protocol'=>1,'signer_sha256'=>'3273d0b0294a689565ab4b0c8ef7e1887e2ca680240718f5521628b5c46328b7','apk_sha256'=>str_repeat('a',64),'artifact_url'=>'https://github.com/derangedchief-crypto/ARVIO/releases/download/brand-'.$brand['id'].'-testing/Brand-synthetic.apk']);};
    $tests['simple trials require explicit per-reseller access after migration, never convert old approvals into live offers']=function()use($app,$config,$owner,$other,$password,&$setup,&$offers,&$policies,&$seller,&$tenant,&$brand,&$artifacts,&$catalogCalls,&$provisions,&$plans,&$c,&$catalogDown):void {
        same(0,(int)$app->db->query('SELECT COUNT(*) FROM trial_plan_grants WHERE live_enabled=1')->fetchColumn());$tenant=$app->management->createReseller($owner,['company'=>'TEST simple trials','name'=>'TEST simple','email'=>'simple-trials@example.test','password'=>$password]);$app->db->query('INSERT INTO panel_resellers (panel_id,tenant_id,username,linked_by) VALUES (?,?,?,?)',['88001001',$tenant['id'],'TEST-simple',$owner['id']]);$seller=$app->db->one('SELECT id,role,tenant_id FROM users WHERE tenant_id=?',[$tenant['id']]);
        $asset=$app->appBrands->upload($seller,['image'=>'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jSuoAAAAASUVORK5CYII=']);$brand=$app->appBrands->save($seller,['name'=>'TEST Simple TV','loading_asset'=>$asset['id'],'logo_asset'=>$asset['id'],'icon_asset'=>$asset['id']]);
        $ownerBrand=$app->db->one("SELECT b.id FROM app_brands b JOIN tenants t ON t.id=b.tenant_id WHERE t.kind='owner'");$c=new ControlCenter\Config($config->root,array_replace($config->values,['trial_worker'=>['shared_secret'=>str_repeat('d',64)],'trial_public_signup_enabled'=>true,'trial_channel'=>'testing','trial_reseller_daily_limit'=>1,'trial_pilot_brand_id'=>$ownerBrand['id'],'trial_owner_unlimited_brand_id'=>$ownerBrand['id']]));
        $plans=[['id'=>71,'name'=>'TEST 24 hours','duration'=>24,'period'=>'hours','max_connections'=>2,'credits'=>'0','bouquets'=>[10],'fingerprint'=>str_repeat('7',64)],['id'=>72,'name'=>'TEST 48 hours','duration'=>48,'period'=>'hours','max_connections'=>2,'credits'=>'0','bouquets'=>[10],'fingerprint'=>str_repeat('8',64)]];
        $worker=new ControlCenter\TrialWorker($c,function($path,$body)use(&$catalogCalls,&$provisions,&$plans,&$catalogDown):string {$s=json_decode($body,true);if($path==='/branded-trials/plans'){$catalogCalls++;if($catalogDown)throw new RuntimeException('SYNTHETIC unavailable worker');return json_encode(['reseller_id'=>$s['reseller_id'],'plans'=>$plans]);}$provisions++;throw new RuntimeException('Settings must never provision an account');});$secrets=new ControlCenter\Secrets($c);$artifacts=new ControlCenter\BrandArtifacts($app->db,$secrets,$c);$policies=new ControlCenter\TrialPolicies($app->db,$app->management,$app->auth,$worker);$offers=new ControlCenter\TrialOffers($app->db,$c,$app->management,$app->auth,$secrets,$policies,$artifacts);$setup=new ControlCenter\TrialSetup($app->db,$app->management,$app->auth,$policies,$offers);
        $global=$offers->globalSettings($owner);if(!$global['enabled'])$offers->setGlobal($owner,['enabled'=>true,'expected_revision'=>$global['revision']]);
        $before=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');$state=$setup->status($seller,[]);same(false,$state['admin_allowed']);same(null,$state['admin']);same(1,$catalogCalls);same($before,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));same(0,$provisions);
        same(false,$offers->publicInfo($brand['id'])['available']);same(false,$offers->publicInfo(str_repeat('0',32))['available']);same(1,$catalogCalls);
        problem(403,fn()=> $setup->saveAdmin($seller,['allowed'=>true]));problem(404,fn()=> $setup->status($other,['tenant_id'=>$tenant['id']]));
    };
    $admin=function(bool $allowed,array $ids=[71,72],int $limit=50)use(&$setup,&$tenant,&$plans,$owner):array {$state=$setup->status($owner,['tenant_id'=>$tenant['id']]);$fingerprints=[];foreach($plans as $p)if(in_array($p['id'],$ids,true))$fingerprints[$p['id']]=$p['fingerprint'];return $setup->saveAdmin($owner,['tenant_id'=>$tenant['id'],'expected_revision'=>$state['admin']['revision'],'allowed'=>$allowed,'allowed_plan_ids'=>$ids,'plan_fingerprints'=>$fingerprints,'daily_limit'=>$limit]);};
    $appInput=function(bool $enabled,int $id=71)use(&$setup,&$seller,&$plans):array {$s=$setup->status($seller,[]);$p=array_column($plans,null,'id')[$id];return ['expected_default_revision'=>$s['settings']['default_revision'],'expected_offer_revision'=>$s['settings']['offer_revision'],'enabled'=>$enabled,'plan_id'=>$id,'plan_fingerprint'=>$p['fingerprint'],'confirmed_public_mode'=>$enabled];};
    $tests['admin allows reseller trials once, sets its own daily cap, and missing APK errors roll back the one-save app request']=function()use($app,$owner,$admin,$appInput,$register,&$setup,&$seller,&$tenant,&$offers,&$brand,&$provisions):void {
        $history=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');$state=$admin(true);same(true,$state['admin_allowed']);same(50,$state['daily_limit']);same(false,$state['active']);same(null,$state['settings']['plan_id']);same(false,$state['settings']['enabled']);
        $before=$app->db->one('SELECT * FROM trial_reseller_defaults WHERE tenant_id=?',[$tenant['id']]);try{$setup->saveApp($seller,$appInput(true));throw new RuntimeException('Expected missing APK rejection');}catch(ControlCenter\Problem $e){same(409,$e->status);check(str_contains($e->getMessage(),'branded APK'));}same($before,$app->db->one('SELECT * FROM trial_reseller_defaults WHERE tenant_id=?',[$tenant['id']]));
        $register('2.0.119',435,1);$state=$setup->saveApp($seller,$appInput(true));same(true,$state['active']);same(50,$offers->admitted($brand['id'])['daily_limit']);same($history,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));same(0,$provisions);
    };
    $tests['unchanged admin saves and ordinary signed APK or cosmetic brand updates do not switch reseller trials off']=function()use($app,$owner,$admin,$register,&$setup,&$seller,&$tenant,&$offers,&$brand):void {
        $before=$offers->publicInfo($brand['id'])['offer_revision'];$default=$app->db->one('SELECT * FROM trial_reseller_defaults WHERE tenant_id=?',[$tenant['id']]);$grant=$app->db->one('SELECT version FROM trial_plan_grants WHERE tenant_id=?',[$tenant['id']]);$admin(true);same($default,$app->db->one('SELECT * FROM trial_reseller_defaults WHERE tenant_id=?',[$tenant['id']]));same($grant,$app->db->one('SELECT version FROM trial_plan_grants WHERE tenant_id=?',[$tenant['id']]));same($before,$offers->publicInfo($brand['id'])['offer_revision']);
        $old=$app->db->one('SELECT * FROM app_brands WHERE id=?',[$brand['id']]);$app->appBrands->save($seller,['expected_version'=>(int)$old['version'],'name'=>'TEST Simple renamed','loading_asset'=>$old['loading_asset'],'logo_asset'=>$old['logo_asset'],'icon_asset'=>$old['icon_asset']]);same($before,$offers->publicInfo($brand['id'])['offer_revision']);$register('2.0.120',436,1);same($before,$offers->publicInfo($brand['id'])['offer_revision']);same(true,$setup->status($seller,[])['active']);
    };
    $tests['admin pause and daily changes retain reseller opt-outs and owner unlimited policy without resetting eligibility']=function()use($app,$owner,$admin,$appInput,&$setup,&$seller,&$tenant,&$offers,&$brand,&$c,&$policies,&$artifacts):void {
        $history=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');$ownerSpace=$app->db->one("SELECT id FROM tenants WHERE kind='owner'");$ownerPub=$app->db->one('SELECT * FROM trial_offer_publications WHERE tenant_id=?',[$ownerSpace['id']]);
        $admin(false);same(false,$offers->publicInfo($brand['id'])['available']);same(true,$setup->status($seller,[])['settings']['enabled']);
        $noPilotConfig=new ControlCenter\Config($c->root,array_replace($c->values,['trial_pilot_brand_id'=>null]));$noPilot=new ControlCenter\TrialOffers($app->db,$noPilotConfig,$app->management,$app->auth,new ControlCenter\Secrets($noPilotConfig),$policies,$artifacts);same(true,$noPilot->paused($brand['id']));
        $admin(true,[71,72],100);same(true,$offers->publicInfo($brand['id'])['available']);same(false,$noPilot->paused($brand['id']));same(100,$offers->admitted($brand['id'])['daily_limit']);
        $state=$setup->status($seller,[]);$setup->saveApp($seller,['expected_offer_revision'=>$state['settings']['offer_revision'],'enabled'=>false]);$admin(true,[71,72],75);same(false,$setup->status($seller,[])['settings']['enabled']);same(false,$offers->publicInfo($brand['id'])['available']);same($ownerPub,$app->db->one('SELECT * FROM trial_offer_publications WHERE tenant_id=?',[$ownerSpace['id']]));same(true,$setup->status($owner,['tenant_id'=>$ownerSpace['id']])['owner_unlimited']);same($history,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));
        $setup->saveApp($seller,$appInput(true));
    };
    $tests['automatic package refresh is read-only and changed terms or stale browser requests fail closed']=function()use($app,$owner,$admin,$appInput,&$setup,&$seller,&$tenant,&$offers,&$brand,&$catalogCalls,&$provisions,&$plans,&$catalogDown):void {
        $stale=$appInput(true);$before=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');$oldCalls=$catalogCalls;$app->db->query('UPDATE trial_plan_catalogs SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE tenant_id=?',[$tenant['id']]);same(false,$app->db->transaction(fn()=> $offers->publicInfo($brand['id']))['available']);same($oldCalls,$catalogCalls);same(true,$offers->publicInfo($brand['id'])['available']);same(true,$setup->status($seller,[])['active']);same($oldCalls+1,$catalogCalls);same(0,$provisions);same($before,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));
        $admin(true,[72]);problem(409,fn()=> $setup->saveApp($seller,$stale));same(false,$offers->publicInfo($brand['id'])['available']);$setup->saveApp($seller,$appInput(true,72));same(true,$offers->publicInfo($brand['id'])['available']);
        $old=$plans[1];$plans[1]['fingerprint']=str_repeat('9',64);$plans[1]['credits']='1';$app->db->query('UPDATE trial_plan_catalogs SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE tenant_id=?',[$tenant['id']]);same(false,$setup->status($seller,[])['active']);$state=$setup->status($owner,['tenant_id'=>$tenant['id']]);problem(409,fn()=> $setup->saveAdmin($owner,['tenant_id'=>$tenant['id'],'expected_revision'=>$state['admin']['revision'],'allowed'=>true,'allowed_plan_ids'=>[72],'plan_fingerprints'=>[72=>$old['fingerprint']],'daily_limit'=>75]));same(0,$provisions);
        $app->db->query('UPDATE trial_plan_catalogs SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE tenant_id=?',[$tenant['id']]);$oldCalls=$catalogCalls;$catalogDown=true;same(false,$offers->publicInfo($brand['id'])['available']);same(false,$offers->publicInfo($brand['id'])['available']);same($oldCalls+1,$catalogCalls);same(0,$provisions);
    };
    $tests['simple trial HTTP routes enforce login CSRF roles closed inputs and workspace isolation']=function()use($app,$owner,$other,$http,$password,&$tenant):void {
        $session=$app->auth->login(['email'=>'simple-trials@example.test','password'=>$password],'127.0.0.252');$h=['Cookie'=>'control_session='.$session['token'],'X-CSRF-Token'=>$session['csrf']];same(401,$http->request('GET','/api/trial-setup',null,[],'simple-anon')['status']);same(403,$http->request('POST','/api/trial-setup/admin',['allowed'=>true],$h,'simple-admin-denied')['status']);same(403,$http->request('POST','/api/trial-setup/app',['enabled'=>false],['Cookie'=>$h['Cookie']],'simple-no-csrf')['status']);same(422,$http->request('POST','/api/trial-setup/app',['enabled'=>false,'owner_unlimited'=>true],$h,'simple-closed')['status']);same(404,$http->request('GET','/api/trial-setup?tenant_id='.$other['tenant_id'],null,$h,'simple-scope')['status']);
    };
    $tests['admin and reseller can always switch OFF without approving stale packages or fixing unfinished numeric edits']=function()use($app,$owner,&$setup,&$seller,&$tenant,&$catalogCalls,&$provisions):void {
        $state=$setup->status($owner,['tenant_id'=>$tenant['id']]);$before=$app->db->one('SELECT allowed_plans,daily_cap FROM trial_plan_grants WHERE tenant_id=?',[$tenant['id']]);$calls=$catalogCalls;$history=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');
        $setup->saveAdmin($owner,['tenant_id'=>$tenant['id'],'expected_revision'=>$state['admin']['revision'],'allowed'=>false,'allowed_plan_ids'=>['unfinished'],'plan_fingerprints'=>[],'daily_limit'=>'unfinished']);same($before,$app->db->one('SELECT allowed_plans,daily_cap FROM trial_plan_grants WHERE tenant_id=?',[$tenant['id']]));
        $state=$setup->status($seller,[]);$result=$setup->saveApp($seller,['expected_offer_revision'=>$state['settings']['offer_revision'],'enabled'=>false,'expected_default_revision'=>'unfinished','plan_id'=>'unfinished','plan_fingerprint'=>'unfinished']);same(false,$result['settings']['enabled']);same($calls,$catalogCalls);same(0,$provisions);same($history,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));
    };
    $tests['explicit owner one-save adoption retains Unlimited and keeps the unchanged offer active across verified APK updates']=function()use($app,$owner,&$setup,&$policies,&$offers,&$artifacts,&$provisions):void {
        $brand=$app->db->one("SELECT b.* FROM app_brands b JOIN tenants t ON t.id=b.tenant_id WHERE t.kind='owner'");$s=$setup->status($owner,['tenant_id'=>$brand['tenant_id']]);same(true,$s['owner_unlimited']);$p=$policies->get($owner,['tenant_id'=>$brand['tenant_id']]);$plan=array_column($p['plans'],null,'id')[(int)$p['default']['plan_id']];$history=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');
        $result=$setup->saveApp($owner,['tenant_id'=>$brand['tenant_id'],'expected_offer_revision'=>$s['settings']['offer_revision'],'expected_default_revision'=>$s['settings']['default_revision'],'enabled'=>true,'plan_id'=>$plan['id'],'plan_fingerprint'=>$plan['fingerprint'],'confirmed_public_mode'=>true]);same(true,$result['active']);same(null,$result['daily_limit']);$before=$offers->publicInfo($brand['id'])['offer_revision'];
        $id=ControlCenter\Database::id();$revision=(int)$brand['version'];$app->db->query('INSERT INTO app_brand_builds (id,brand_id,brand_version,app_version,manifest,requested_by,build_channel) VALUES (?,?,?,?,?,?,?)',[$id,$brand['id'],$revision,'2.0.121',json_encode(['app_version'=>'2.0.121','app_version_code'=>437]),$owner['id'],'testing']);$artifacts->recordVerified($id,['channel'=>'testing','package_name'=>$brand['package_name'].'.test','version_name'=>'2.0.121.'.$revision.'-test','version_code'=>43700000+$revision,'trial_protocol'=>1,'signer_sha256'=>'3273d0b0294a689565ab4b0c8ef7e1887e2ca680240718f5521628b5c46328b7','apk_sha256'=>str_repeat('a',64),'artifact_url'=>'https://github.com/derangedchief-crypto/ARVIO/releases/download/brand-'.$brand['id'].'-testing/Brand-synthetic.apk']);same($before,$offers->publicInfo($brand['id'])['offer_revision']);same(true,$setup->status($owner,['tenant_id'=>$brand['tenant_id']])['active']);same(0,$provisions);same($history,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));
    };
}
